import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Button,
  Input,
  LinPageLayout,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useFinancialIndicatorsPermissions } from '../../../hooks/useFinancialIndicatorsPermissions';
import {
  listFinancialIndicators,
  runFinancialIndicator,
  type FinancialIndicatorColumn,
  type FinancialIndicatorListItem,
} from '../../../services/kt/financialIndicators';
import { useAppDispatch } from '../../../store/hooks';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { formatMoney } from '../../../utils/formatters';
import erp from '../../../styles/erpPage.module.css';

const TEST_ID = 'kt-chi-tieu-tai-chinh';
const PAGE_ID = 'kt-chi-tieu-tai-chinh';
const TITLE = 'Chỉ tiêu tài chính';
const MA_PHAN_HE = 'GL';

const ALLOWLIST = new Set([
  'GL_KPI_DT',
  'GL_KPI_DT_BE_RO',
  'GL_KPI_CP',
  'GL_KPI_CP641',
  'GL_KPI_CP642',
]);

const FALLBACK_COLUMNS: Record<string, FinancialIndicatorColumn[]> = {
  GL_KPI_DT: [
    { key: 'tenTk', label: 'Tên TK', align: 'left' },
    { key: 'dt', label: 'Doanh thu', align: 'right' },
  ],
  GL_KPI_DT_BE_RO: [
    { key: 'tenDt', label: 'Nhóm DT', align: 'left' },
    { key: 'dt', label: 'Doanh thu', align: 'right' },
  ],
  GL_KPI_CP: [
    { key: 'tenCp', label: 'Khoản mục', align: 'left' },
    { key: 'cp', label: 'Chi phí', align: 'right' },
  ],
  GL_KPI_CP641: [
    { key: 'maPhi', label: 'Mã phí', align: 'left' },
    { key: 'tenPhi', label: 'Tên phí', align: 'left' },
    { key: 'cp', label: 'Chi phí', align: 'right' },
  ],
  GL_KPI_CP642: [
    { key: 'maPhi', label: 'Mã phí', align: 'left' },
    { key: 'tenPhi', label: 'Tên phí', align: 'left' },
    { key: 'cp', label: 'Chi phí', align: 'right' },
  ],
};

const FALLBACK_TITLE: Record<string, string> = {
  GL_KPI_DT: 'CƠ CẤU DOANH THU',
  GL_KPI_DT_BE_RO: 'CƠ CẤU DOANH THU',
  GL_KPI_CP: 'CƠ CẤU CHI PHÍ',
  GL_KPI_CP641: 'CƠ CẤU CHI PHÍ BÁN HÀNG',
  GL_KPI_CP642: 'CƠ CẤU CHI PHÍ QUẢN LÝ',
};

const MONEY_KEYS = new Set(['dt', 'cp']);

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function normalizePeriod(ngayCt1: string, ngayCt2: string): { ngayCt1: string; ngayCt2: string } | null {
  let a = ngayCt1.trim();
  let b = ngayCt2.trim();
  if (a && !b) b = a;
  if (b && !a) a = b;
  if (!a && !b) return null;
  if (a > b) return { ngayCt1: b, ngayCt2: a };
  return { ngayCt1: a, ngayCt2: b };
}

function cellText(value: unknown): string {
  if (value == null) return '—';
  const text = String(value).trim();
  return text.length === 0 ? '—' : text;
}

function cellMoney(value: unknown): string {
  const n = typeof value === 'number' ? value : Number(value);
  if (!Number.isFinite(n)) return formatMoney(0);
  return formatMoney(n);
}

const ChiTieuTaiChinhPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const { canRead } = useFinancialIndicatorsPermissions();

  const [ngayCt1, setNgayCt1] = useState('');
  const [ngayCt2, setNgayCt2] = useState('');
  const [kpiItems, setKpiItems] = useState<FinancialIndicatorListItem[]>([]);
  const [selectedMaKpi, setSelectedMaKpi] = useState<string | null>(null);
  const [resultTitle, setResultTitle] = useState('');
  const [resultColumns, setResultColumns] = useState<FinancialIndicatorColumn[]>([]);
  const [resultItems, setResultItems] = useState<Record<string, unknown>[]>([]);
  const [lastRunMaKpi, setLastRunMaKpi] = useState<string | null>(null);
  const [hasRun, setHasRun] = useState(false);
  const [listLoading, setListLoading] = useState(false);
  const [runLoading, setRunLoading] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);

  const busy = listLoading || runLoading;
  const { showTableLoading } = useCatalogTableBusy(busy);

  const loadList = useCallback(async () => {
    setListLoading(true);
    try {
      const data = await listFinancialIndicators();
      const items = data.items ?? [];
      setKpiItems(items);
      setSelectedMaKpi(prev => (prev && items.some(x => x.maKpi === prev) ? prev : null));
    } catch (err) {
      setKpiItems([]);
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, 'Không tải được danh sách chỉ tiêu'),
        type: 'error',
      });
    } finally {
      setListLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    void loadList();
  }, [loadList, reloadKey]);

  const runKpi = useCallback(
    async (maKpi: string) => {
      setSelectedMaKpi(maKpi);

      const company = sessionCompany();
      if (!company) {
        dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
        return;
      }

      const period = normalizePeriod(ngayCt1, ngayCt2);
      if (!period) {
        dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
        return;
      }

      const code = maKpi.trim();
      if (!code) {
        dispatchAppToast(dispatch, { message: 'Chọn chỉ tiêu', type: 'error' });
        return;
      }
      if (!ALLOWLIST.has(code)) {
        dispatchAppToast(dispatch, { message: 'Chỉ tiêu không hợp lệ', type: 'error' });
        return;
      }

      setRunLoading(true);
      try {
        const data = await runFinancialIndicator({
          ngayCt1: period.ngayCt1,
          ngayCt2: period.ngayCt2,
          maKpi: code,
          maPhanHe: MA_PHAN_HE,
        });
        const columns =
          data.columns && data.columns.length > 0
            ? data.columns
            : FALLBACK_COLUMNS[code] ?? [];
        setResultTitle((data.title || FALLBACK_TITLE[code] || '').trim());
        setResultColumns(columns);
        setResultItems(data.items ?? []);
        setLastRunMaKpi(code);
        setHasRun(true);
      } catch (err) {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không chạy được chỉ tiêu'),
          type: 'error',
        });
      } finally {
        setRunLoading(false);
      }
    },
    [dispatch, ngayCt1, ngayCt2],
  );

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: busy,
        onClick: () => setReloadKey(k => k + 1),
      },
    ],
    [busy],
  );

  const displayColumns =
    resultColumns.length > 0
      ? resultColumns
      : lastRunMaKpi
        ? FALLBACK_COLUMNS[lastRunMaKpi] ?? []
        : [];

  if (!canRead) {
    return (
      <div className={erp.voucherListRoot} data-testid={`${TEST_ID}-denied`}>
        <p className={erp.empty}>Bạn không có quyền xem chỉ tiêu tài chính.</p>
      </div>
    );
  }

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{
          title: TITLE,
          titleIconClass: 'fas fa-chart-pie',
        }}
        listTitle={TITLE}
        filterMaxWidthPx={720}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        filters={(
          <>
            <label>
              Từ ngày
              <Input
                type="date"
                value={ngayCt1}
                onChange={e => setNgayCt1(e.target.value)}
                data-testid={`${TEST_ID}-field-ngayCt1`}
              />
            </label>
            <label>
              Đến ngày
              <Input
                type="date"
                value={ngayCt2}
                onChange={e => setNgayCt2(e.target.value)}
                data-testid={`${TEST_ID}-field-ngayCt2`}
              />
            </label>
          </>
        )}
        footer={
          hasRun ? (
            <div className={erp.paginationRow} data-testid={`${TEST_ID}-summary`}>
              Tổng: {resultItems.length} dòng
            </div>
          ) : undefined
        }
      >
        <div>
          <div className={erp.tableWrapper}>
            <table className={erp.table} data-testid={`${TEST_ID}-kpi-list`}>
              <thead>
                <tr>
                  <th>Chỉ tiêu</th>
                  <th style={{ width: 96, textAlign: 'right' }} />
                </tr>
              </thead>
              <tbody>
                {kpiItems.length === 0 && !listLoading ? (
                  <tr>
                    <td colSpan={2}>
                      <div className={erp.empty} data-testid={`${TEST_ID}-kpi-empty`}>
                        Không có chỉ tiêu
                      </div>
                    </td>
                  </tr>
                ) : (
                  kpiItems.map(row => (
                    <tr
                      key={row.maKpi}
                      data-testid={`${TEST_ID}-kpi-row-${row.maKpi}`}
                      aria-selected={selectedMaKpi === row.maKpi}
                    >
                      <td>{row.tenKpi}</td>
                      <td style={{ textAlign: 'right' }}>
                        <Button
                          variant="primary"
                          disabled={busy}
                          data-testid={`${TEST_ID}-run-btn-${row.maKpi}`}
                          onClick={() => void runKpi(row.maKpi)}
                        >
                          Xem
                        </Button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>

          {hasRun ? (
            <h3 data-testid={`${TEST_ID}-result-title`} style={{ margin: '16px 0 8px' }}>
              {resultTitle}
            </h3>
          ) : null}

          {!hasRun && !runLoading ? (
            <div className={erp.empty} data-testid={`${TEST_ID}-result-empty`}>
              Chọn chỉ tiêu và bấm Xem
            </div>
          ) : null}

          {hasRun ? (
            <div className={erp.tableWrapper}>
              <table className={erp.table} data-testid={`${TEST_ID}-result-grid`}>
                <thead>
                  <tr>
                    {displayColumns.map(col => (
                      <th
                        key={col.key}
                        className={col.align === 'right' ? erp.colRight : undefined}
                      >
                        {col.label}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {resultItems.length === 0 ? (
                    <tr>
                      <td colSpan={Math.max(displayColumns.length, 1)}>
                        <div className={erp.empty} data-testid={`${TEST_ID}-result-empty`}>
                          Không có dữ liệu
                        </div>
                      </td>
                    </tr>
                  ) : (
                    resultItems.map((row, index) => (
                      <tr key={index} data-testid={`${TEST_ID}-result-row-${index}`}>
                        {displayColumns.map(col => {
                          const raw = row[col.key];
                          const isMoney = MONEY_KEYS.has(col.key) || col.align === 'right';
                          return (
                            <td
                              key={col.key}
                              className={col.align === 'right' ? erp.colRight : undefined}
                            >
                              {isMoney && typeof raw !== 'string'
                                ? cellMoney(raw)
                                : MONEY_KEYS.has(col.key)
                                  ? cellMoney(raw)
                                  : cellText(raw)}
                            </td>
                          );
                        })}
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          ) : null}
        </div>
      </LinPageLayout>
    </div>
  );
};

export default ChiTieuTaiChinhPage;
