import { apiClient, unwrap, type BffResponse } from '../api';

export interface FinancialIndicatorListItem {
  maKpi: string;
  tenKpi: string;
}

export interface FinancialIndicatorListDto {
  items: FinancialIndicatorListItem[];
}

export interface FinancialIndicatorColumn {
  key: string;
  label: string;
  align?: 'left' | 'right' | string;
}

export interface FinancialIndicatorRunResult {
  maKpi: string;
  title: string;
  columns: FinancialIndicatorColumn[];
  items: Record<string, unknown>[];
}

export interface FinancialIndicatorRunBody {
  ngayCt1: string;
  ngayCt2: string;
  maKpi: string;
  maPhanHe?: string;
}

export async function listFinancialIndicators(): Promise<FinancialIndicatorListDto> {
  const res = await apiClient.get<BffResponse<FinancialIndicatorListDto>>(
    '/accounting/financial-indicators?maPhanHe=GL',
  );
  return unwrap(res) ?? { items: [] };
}

export async function runFinancialIndicator(
  body: FinancialIndicatorRunBody,
): Promise<FinancialIndicatorRunResult> {
  const res = await apiClient.post<BffResponse<FinancialIndicatorRunResult>>(
    '/accounting/financial-indicators/run',
    {
      ngayCt1: body.ngayCt1,
      ngayCt2: body.ngayCt2,
      maKpi: body.maKpi,
      maPhanHe: body.maPhanHe ?? 'GL',
    },
  );
  return unwrap(res);
}
